package com.example.takura.media.application;

import com.example.takura.identity.application.PermissionService;
import com.example.takura.identity.domain.StaffPrincipal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.sql.Timestamp;
import java.time.Clock;
import java.time.Duration;
import java.time.temporal.ChronoUnit;
import java.util.Base64;
import java.util.HexFormat;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.UUID;
import java.util.regex.Pattern;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class UploadService {
    private static final int MAX_FILES=5;private static final long MAX_FILE=10L*1024*1024,MAX_TOTAL=50L*1024*1024;
    private static final Pattern CHECKSUM=Pattern.compile("^[a-fA-F0-9]{64}$");
    private static final Set<String> EXTENSIONS=Set.of("jpg","jpeg","png","webp","pdf","xlsx");
    private static final Set<String> TYPES=Set.of("image/jpeg","image/png","image/webp","application/pdf","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
    private final JdbcTemplate jdbc;private final TransactionTemplate transactions;private final ObjectStoragePort storage;private final AttachmentValidator validator;private final PermissionService permissions;private final Clock clock;private final SecureRandom random=new SecureRandom();
    public UploadService(JdbcTemplate jdbc,TransactionTemplate transactions,ObjectStoragePort storage,AttachmentValidator validator,PermissionService permissions,Clock clock){this.jdbc=jdbc;this.transactions=transactions;this.storage=storage;this.validator=validator;this.permissions=permissions;this.clock=clock;}

    public SessionResponse createCustomer(CreateSession request,String source){return create(request,"CUSTOMER_ATTACHMENT",null,source);}
    public SessionResponse createStaff(StaffPrincipal actor,CreateSession request){permissions.require(actor,"content:write");return create(request,"STAFF_MEDIA",actor.identityId(),actor.identityId().toString());}
    private SessionResponse create(CreateSession request,String purpose,UUID owner,String source){validateFiles(request.files(),purpose);String risk=sha(source==null?"unknown":source);var now=clock.instant();
        Integer recent=jdbc.queryForObject("SELECT count(*) FROM takura.upload_session WHERE risk_hash=? AND created_at>?",Integer.class,risk,Timestamp.from(now.minus(10,ChronoUnit.MINUTES)));if(recent!=null&&recent>=10)throw error(HttpStatus.TOO_MANY_REQUESTS,"RATE_LIMITED","Upload session quota exceeded; wait before retrying.");
        long bytes=request.files().stream().mapToLong(FileRequest::byteSize).sum();Long allocated=jdbc.queryForObject("SELECT COALESCE(sum(allocated_bytes),0) FROM takura.upload_session WHERE state='ACTIVE' AND expires_at>?",Long.class,Timestamp.from(now));if(allocated!=null&&allocated+bytes>1024L*1024*1024)throw error(HttpStatus.SERVICE_UNAVAILABLE,"UPLOAD_CAPACITY_REACHED","Temporary upload capacity is unavailable.");
        UUID session=UUID.randomUUID();String capability=token();String capabilityHash=sha(capability);var expires=now.plus(Duration.ofMinutes(60));
        List<Allocation> allocations=transactions.execute(status->{jdbc.query("SELECT pg_advisory_xact_lock(hashtext('upload-capacity'))",rs->{rs.next();return null;});jdbc.query("SELECT pg_advisory_xact_lock(hashtext(?))",rs->{rs.next();return null;},risk);Long current=jdbc.queryForObject("SELECT COALESCE(sum(allocated_bytes),0) FROM takura.upload_session WHERE state='ACTIVE' AND expires_at>?",Long.class,Timestamp.from(now));if(current!=null&&current+bytes>1024L*1024*1024)throw error(HttpStatus.SERVICE_UNAVAILABLE,"UPLOAD_CAPACITY_REACHED","Temporary upload capacity is unavailable.");jdbc.update("INSERT INTO takura.upload_session(id,capability_hash,purpose,owner_identity_id,risk_hash,state,allocated_files,allocated_bytes,created_at,expires_at) VALUES(?,?,?,?,?,'ACTIVE',?,?,?,?)",session,capabilityHash,purpose,owner,risk,request.files().size(),bytes,Timestamp.from(now),Timestamp.from(expires));var list=new java.util.ArrayList<Allocation>();for(FileRequest file:request.files()){UUID id=UUID.randomUUID();String ext=extension(file.fileName()),safe="attachment-"+(list.size()+1)+"."+ext,key="quarantine/"+session+"/"+id;jdbc.update("INSERT INTO takura.attachment(id,upload_session_id,safe_display_name,extension,declared_content_type,expected_bytes,expected_checksum_sha256,staging_key,state,created_at,cleanup_eligible_at) VALUES(?,?,?,?,?,?,?,?,'CREATED',?,?)",id,session,safe,ext,file.contentType().toLowerCase(Locale.ROOT),file.byteSize(),file.checksumSha256().toLowerCase(Locale.ROOT),key,Timestamp.from(now),Timestamp.from(now.plus(30,ChronoUnit.DAYS)));list.add(new Allocation(id,safe,key,file.byteSize(),file.contentType(),file.checksumSha256(),null));}return List.copyOf(list);});
        long perFile="STAFF_MEDIA".equals(purpose)?100L*1024*1024:MAX_FILE,total="STAFF_MEDIA".equals(purpose)?100L*1024*1024:MAX_TOTAL;return new SessionResponse(session,capability,expires,MAX_FILES,perFile,total,allocations.stream().map(a->withPost(a,capability)).toList());}
    public Allocation renew(UUID session,UUID attachment,String capability){SessionRow row=requireSession(session,capability);quotaStillAvailable(row.riskHash());var a=attachment(session,attachment);if(!Set.of("CREATED","UPLOADING").contains(a.state()))throw error(HttpStatus.CONFLICT,"STATE_CONFLICT","This upload can no longer be renewed.");return withPost(a.toAllocation(),capability);}
    public Completion complete(UUID session,UUID attachmentId,String capability){SessionRow sessionRow=requireSession(session,capability);var attachment=attachment(session,attachmentId);if(Set.of("VALIDATING","SCAN_PENDING","CLEAN","REJECTED").contains(attachment.state()))return new Completion(attachment.id(),attachment.state(),attachment.rejectionCode());if(!Set.of("CREATED","UPLOADING").contains(attachment.state()))throw error(HttpStatus.CONFLICT,"STATE_CONFLICT","The attachment cannot be completed from its current state.");
        ObjectStoragePort.StoredObject uploaded;try{uploaded=storage.headStaging(attachment.stagingKey());}catch(RuntimeException missing){throw error(HttpStatus.CONFLICT,"UPLOAD_INCOMPLETE","The assigned upload object is not available.");}
        if(uploaded.byteSize()!=attachment.expectedBytes()||!attachment.expectedChecksum().equalsIgnoreCase(uploaded.checksumSha256())||!attachment.declaredType().equalsIgnoreCase(uploaded.contentType())||!attachment.id().toString().equals(uploaded.metadata().get("attachment-id")))throw error(HttpStatus.CONFLICT,"UPLOAD_METADATA_MISMATCH","Uploaded bytes do not match the assigned key, size, type or checksum.");
        String privateKey="private/"+attachment.id()+"/original."+attachment.extension();var pinned=storage.pinToPrivate(attachment.stagingKey(),uploaded.version(),privateKey);
        transactions.executeWithoutResult(tx->jdbc.update("UPDATE takura.attachment SET state='VALIDATING',staging_version=?,private_key=?,private_version=?,verified_checksum_sha256=?,completed_at=?,revision=revision+1 WHERE id=? AND state IN ('CREATED','UPLOADING')",uploaded.version(),privateKey,pinned.version(),attachment.expectedChecksum(),Timestamp.from(clock.instant()),attachment.id()));
        byte[] bytes=storage.readPrivate(privateKey,pinned.version());var structural=validator.validate(attachment.extension(),bytes);if(!structural.accepted()){reject(attachment.id(),structural.rejectionCode());return new Completion(attachment.id(),"REJECTED",structural.rejectionCode());}
        transactions.executeWithoutResult(tx->{jdbc.update("UPDATE takura.attachment SET state='SCAN_PENDING',revision=revision+1 WHERE id=? AND state='VALIDATING'",attachment.id());jdbc.update("INSERT INTO takura.attachment_scan_job(attachment_id,state,next_attempt_at,created_at) VALUES(?,'PENDING',?,?) ON CONFLICT(attachment_id) DO NOTHING",attachment.id(),Timestamp.from(clock.instant()),Timestamp.from(clock.instant()));});return new Completion(attachment.id(),"SCAN_PENDING",null);}
    public void associateWithEnquiry(UUID enquiry,List<String> ids,String capability){if(ids==null||ids.isEmpty())return;if(capability==null||capability.isBlank())throw error(HttpStatus.BAD_REQUEST,"UPLOAD_CAPABILITY_REQUIRED","The upload capability is required to attach files.");if(ids.size()>MAX_FILES||ids.stream().distinct().count()!=ids.size())throw error(HttpStatus.BAD_REQUEST,"ATTACHMENT_LIMIT","Attach at most five distinct files.");String hash=sha(capability);var attachments=ids.stream().map(value->{try{return UUID.fromString(value);}catch(Exception invalid){throw error(HttpStatus.BAD_REQUEST,"ATTACHMENT_INVALID","An attachment identifier is invalid.");}}).toList();for(UUID id:attachments){Integer valid=jdbc.queryForObject("SELECT count(*) FROM takura.attachment a JOIN takura.upload_session s ON s.id=a.upload_session_id WHERE s.capability_hash=? AND s.purpose='CUSTOMER_ATTACHMENT' AND a.id=? AND a.enquiry_id IS NULL AND a.state NOT IN ('REJECTED','FAILED','EXPIRED','DELETION_PENDING','DELETED')",Integer.class,hash,id);if(valid==null||valid!=1)throw error(HttpStatus.BAD_REQUEST,"ATTACHMENT_REJECTED","Remove rejected, expired, already-associated or unowned attachments before submitting.");}for(UUID id:attachments){if(jdbc.update("UPDATE takura.attachment SET enquiry_id=? WHERE id=? AND enquiry_id IS NULL",enquiry,id)!=1)throw error(HttpStatus.CONFLICT,"ATTACHMENT_CONFLICT","An attachment was associated concurrently.");jdbc.update("INSERT INTO takura.enquiry_attachment(enquiry_id,attachment_id,associated_at) VALUES(?,?,?)",enquiry,id,Timestamp.from(clock.instant()));}}
    public java.net.URI staffDownload(StaffPrincipal actor,UUID attachment){if(!(actor.may("enquiry:assigned:read")||actor.may("enquiry:all:read")||actor.may("record:granted:read")))throw new org.springframework.security.access.AccessDeniedException("Attachment access is not granted");var rows=jdbc.query("SELECT a.private_key,a.private_version FROM takura.attachment a JOIN takura.enquiry e ON e.id=a.enquiry_id WHERE a.id=? AND a.state='CLEAN' AND ("+scope(actor)+")",(rs,n)->new String[]{rs.getString(1),rs.getString(2)},attachment);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"ATTACHMENT_NOT_FOUND","The clean attachment was not found in your scope.");audit(actor.identityId(),attachment,"DOWNLOAD_LINK_ISSUED","ALLOWED");return storage.createPrivateDownload(rows.getFirst()[0],rows.getFirst()[1],Duration.ofMinutes(5));}
    public List<AttachmentView> enquiryAttachments(StaffPrincipal actor,UUID enquiry){if(!(actor.may("enquiry:assigned:read")||actor.may("enquiry:all:read")||actor.may("record:granted:read")))throw new org.springframework.security.access.AccessDeniedException("Attachment access is not granted");return jdbc.query("SELECT a.id,a.safe_display_name,a.declared_content_type,a.expected_bytes,a.state,a.rejection_code FROM takura.attachment a JOIN takura.enquiry e ON e.id=a.enquiry_id WHERE e.id=? AND ("+scope(actor)+") ORDER BY a.created_at",(rs,n)->new AttachmentView((UUID)rs.getObject(1),rs.getString(2),rs.getString(3),rs.getLong(4),rs.getString(5),rs.getString(6)),enquiry);}
    private String scope(StaffPrincipal p){if(p.may("enquiry:all:read"))return "TRUE";String grant="EXISTS(SELECT 1 FROM takura.enquiry_record_grant g WHERE g.enquiry_id=e.id AND g.staff_identity_id='"+p.identityId()+"')";String teams=p.teams().stream().filter(Set.of("PROPERTY","CABINETRY","BOARDS","GENERAL")::contains).map(t->"'"+t+"'").collect(java.util.stream.Collectors.joining(","));return teams.isEmpty()?grant:"((e.team_code IN ("+teams+") AND (e.owner_identity_id IS NULL OR e.owner_identity_id='"+p.identityId()+"')) OR "+grant+")";}
    private Allocation withPost(Allocation a,String capability){var post=storage.createUploadPost(a.stagingKey(),a.byteSize(),a.contentType(),a.checksum(),a.attachmentId().toString(),Duration.ofMinutes(5));jdbc.update("UPDATE takura.attachment SET state='UPLOADING' WHERE id=? AND state='CREATED'",a.attachmentId());return new Allocation(a.attachmentId(),a.safeDisplayName(),a.stagingKey(),a.byteSize(),a.contentType(),a.checksum(),new UploadInstructions("POST",post.url(),post.fields(),post.expiresAt()));}
    private SessionRow requireSession(UUID id,String capability){if(capability==null)return invalidCapability();var rows=jdbc.query("SELECT risk_hash,expires_at,state FROM takura.upload_session WHERE id=? AND capability_hash=?",(rs,n)->new SessionRow(rs.getString(1),rs.getTimestamp(2).toInstant(),rs.getString(3)),id,sha(capability));if(rows.isEmpty())return invalidCapability();var row=rows.getFirst();if(!"ACTIVE".equals(row.state())||!row.expiresAt().isAfter(clock.instant())){jdbc.update("UPDATE takura.upload_session SET state='EXPIRED' WHERE id=? AND state='ACTIVE'",id);throw error(HttpStatus.GONE,"UPLOAD_EXPIRED","The upload session expired.");}return row;}
    private SessionRow invalidCapability(){throw error(HttpStatus.NOT_FOUND,"UPLOAD_SESSION_NOT_FOUND","The upload session was not found.");}
    private void quotaStillAvailable(String risk){Integer recent=jdbc.queryForObject("SELECT count(*) FROM takura.upload_session WHERE risk_hash=? AND created_at>?",Integer.class,risk,Timestamp.from(clock.instant().minus(10,ChronoUnit.MINUTES)));if(recent!=null&&recent>10)throw error(HttpStatus.TOO_MANY_REQUESTS,"RATE_LIMITED","Upload renewal quota exceeded.");}
    private AttachmentRow attachment(UUID session,UUID id){var rows=jdbc.query("SELECT id,staging_key,expected_bytes,expected_checksum_sha256,declared_content_type,extension,safe_display_name,state,rejection_code FROM takura.attachment WHERE upload_session_id=? AND id=?",(rs,n)->new AttachmentRow((UUID)rs.getObject(1),rs.getString(2),rs.getLong(3),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7),rs.getString(8),rs.getString(9)),session,id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"ATTACHMENT_NOT_FOUND","The attachment was not found.");return rows.getFirst();}
    private void reject(UUID id,String code){jdbc.update("UPDATE takura.attachment SET state='REJECTED',rejection_code=?,scan_completed_at=?,revision=revision+1 WHERE id=?",code,Timestamp.from(clock.instant()),id);}
    private void audit(UUID actor,UUID attachment,String action,String outcome){jdbc.update("INSERT INTO takura.storage_audit_event(id,actor_identity_id,attachment_id,action,outcome,occurred_at) VALUES(?,?,?,?,?,?)",UUID.randomUUID(),actor,attachment,action,outcome,Timestamp.from(clock.instant()));}
    private static void validateFiles(List<FileRequest> files,String purpose){if(files==null||files.isEmpty()||files.size()>MAX_FILES)throw error(HttpStatus.BAD_REQUEST,"ATTACHMENT_LIMIT","Allocate one to five files.");boolean staff="STAFF_MEDIA".equals(purpose);long maxFile=staff?100L*1024*1024:MAX_FILE,maxTotal=staff?100L*1024*1024:MAX_TOTAL,total=0;for(FileRequest f:files){String ext=extension(f.fileName()),type=f.contentType().toLowerCase(Locale.ROOT);boolean video=staff&&"mp4".equals(ext)&&"video/mp4".equals(type);if((!EXTENSIONS.contains(ext)||!TYPES.contains(type))&&!video)throw error(HttpStatus.BAD_REQUEST,"FILE_TYPE_FORBIDDEN",staff?"Use an allowed image, document or reviewed MP4.":"Use JPEG, PNG, WebP, PDF or non-macro XLSX.");if(f.byteSize()<1||f.byteSize()>maxFile)throw error(HttpStatus.BAD_REQUEST,"FILE_TOO_LARGE",staff?"Staff media must be no larger than 100 MiB.":"Each file must be no larger than 10 MiB.");if(!CHECKSUM.matcher(f.checksumSha256()).matches())throw error(HttpStatus.BAD_REQUEST,"CHECKSUM_INVALID","Provide a SHA-256 checksum.");total+=f.byteSize();}if(total>maxTotal)throw error(HttpStatus.BAD_REQUEST,"UPLOAD_TOTAL_TOO_LARGE",staff?"Combined staff media must be no larger than 100 MiB.":"Combined files must be no larger than 50 MiB.");}
    private static String extension(String name){if(name==null)return "";int i=name.lastIndexOf('.');return i<0?"":name.substring(i+1).toLowerCase(Locale.ROOT);}
    private String token(){byte[] bytes=new byte[32];random.nextBytes(bytes);return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
    private static String sha(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private static UploadException error(HttpStatus status,String code,String message){return new UploadException(status,code,message);}
    public static final class UploadException extends RuntimeException { public final HttpStatus status; public final String code; public UploadException(HttpStatus status,String code,String message){super(message);this.status=status;this.code=code;} }
    public record FileRequest(String fileName,long byteSize,String contentType,String checksumSha256){}
    public record CreateSession(List<FileRequest> files){}
    public record SessionResponse(UUID sessionId,String capability,java.time.Instant expiresAt,int maxFiles,long maxBytesPerFile,long maxCombinedBytes,List<Allocation> files){}
    public record Allocation(UUID attachmentId,String safeDisplayName,String stagingKey,long byteSize,String contentType,String checksum,UploadInstructions upload){}
    public record UploadInstructions(String method,java.net.URI url,java.util.Map<String,String> fields,java.time.Instant expiresAt){}
    public record Completion(UUID attachmentId,String state,String rejectionCode){}
    public record AttachmentView(UUID id,String displayName,String contentType,long byteSize,String state,String rejectionCode){}
    private record SessionRow(String riskHash,java.time.Instant expiresAt,String state){}
    private record AttachmentRow(UUID id,String stagingKey,long expectedBytes,String expectedChecksum,String declaredType,String extension,String safeName,String state,String rejectionCode){Allocation toAllocation(){return new Allocation(id,safeName,stagingKey,expectedBytes,declaredType,expectedChecksum,null);}}
}
